(function () { 'use strict'; var tabs = document.querySelectorAll('.tk-tab-btn'); var panels = document.querySelectorAll('.tk-panel'); var hiddens = document.querySelectorAll('input[name="rodolfo_active_tab"]'); if (!tabs.length || !panels.length) { return; } function activate(slug) { tabs.forEach(function (t) { t.classList.toggle('is-active', t.dataset.tab === slug); }); panels.forEach(function (p) { p.classList.toggle('is-active', p.dataset.panel === slug); }); hiddens.forEach(function (h) { h.value = slug; }); var footer = document.querySelector('.tk-form-footer'); if (footer) { footer.style.display = (slug === 'docs') ? 'none' : ''; } try { var url = new URL(window.location.href); url.searchParams.set('tab', slug); history.replaceState(null, '', url.toString()); } catch (e) { } } tabs.forEach(function (t) { t.addEventListener('click', function (e) { e.preventDefault(); activate(t.dataset.tab); }); }); })();